void __fastcall RecPcRoll(uint8_t* o, int, float d) { Logf("roll %08x", B(d)); }
int32_t __fastcall FakePcContains(void* m, int, float x, float y) { Logf("contains %08x %08x", B(x), B(y)); return g_pc.contains; }
