        *(float*)(scene + 0x22b83) = RndF(0.0f, 3.0f);
        *(int32_t*)(scene + 0x22b7b) = (int32_t)(Rnd() % 50000);
        *(int32_t*)(scene + 0xd) = (int32_t)(Rnd() % 50000);
        *(int32_t*)(render + 0x370d) = (int32_t)(Rnd() % 5000);
