        for (int k = 0; k < 0x35; ++k) *(float*)(g_clRegion + 0x103 + k * 4) = RndF(0.0f, 9.0f);
        *(float*)(g_clBuilding + 0x1e2) = RndF(0.0f, 500.0f);
