        *(int32_t*)(world + 0x4aef) = Rnd() % 20 == 0;
        world[0x4c8d] = Rnd() % 4 == 0;
        *(uint16_t*)(world + 0xd) = (uint16_t)(1830 + Rnd() % 180);
