        strcpy((char*)g_ipRec + 0x4f, "Mill");
        *(uint32_t*)(g_ipRec + 0x22) = Rnd() % 8 == 0 ? 0x80000000u + Rnd() % 1000 : Rnd() % 400000;
        *(float*)(g_ipRec + 0x2a) = IpRndF(0.0f, 30.0f);
