    t.Add(0x518380, (void*)&rt3::Collection_IdAt, (void*)&FakePqIdAt);
    t.Add(0x518140, (void*)&rt3::Collection_Get, (void*)&FakePqGet);
    t.Add(0x4101e0, (void*)&rt3::Industry_Produce, (void*)&RecPqProduce);
