            ((uint32_t*)0x62b318)[n0] = 0xffffffff;
            hook::Global<int32_t>(0x62b7a4) = n0;
            hook::Global<int32_t>(0x62b7a8) = 3;
            hook::Global<int32_t>(0x62b7ac) = 0;
            hook::Global<int32_t>(0x62b7b0) = 2;
