std::string B55ReadFile(const char* p) {
    std::string s;
    FILE* f = fopen(p, "rb");
    if (!f) return "<none>";
    char b[512];
    size_t n;
    while ((n = fread(b, 1, sizeof b, f)) > 0) s.append(b, n);
    fclose(f);
    return s;
}
