DIFFTEST(net_ProcessIncoming) {
    UiTrace t;
    t.Add(0x522f70, (void*)&rt3::Net_TakeChannelMessages, (void*)&FakeB83Take);
    t.Add(0x522050, (void*)&rt3::Textures_Lookup, (void*)&FakeB83Lookup);
    t.Add(0x46ac00, (void*)&rt3::Net_Dispatch, (void*)&FakeB83Dispatch);
    t.Add(0x469800, (void*)&rt3::NetPacket_Alloc, (void*)&FakeB83Alloc);
    t.Add(0x53d4c0, (void*)&rt3::Heap_Push, (void*)&FakeB83Push);
    t.Add(0x523010, (void*)&rt3::Net_FinishReceived, (void*)&FakeB83Finish);
    t.Add(0x46d300, (void*)&rt3::Net_FeedResync, (void*)&FakeB83Feed);
    t.Add(0x521d40, (void*)&rt3::Engine_FirstListEntry, (void*)&FakeB83Entry);
    *(void**)(g_b83Entry + 0x6c) = (void*)0x4444;
    static uint8_t s[0x9900];
    *(void**)(s + 8) = (void*)&FakeB83Raw;
    for (int it = 0; it < 500; ++it) {
        g_b83HasList = Rnd() % 6 != 0;
        int n = Rnd() % 6;
        uint8_t init[6][0x30], hinit[6][0x40];
        for (int k = 0; k < 6; ++k) {
            for (int b = 0; b < 0x30; ++b) init[k][b] = (uint8_t)Rnd();
            for (int b = 0; b < 0x40; ++b) hinit[k][b] = (uint8_t)Rnd();
            *(int32_t*)(init[k] + 0x10) = Rnd() % 4 == 0;
            init[k][0x18] = (uint8_t)(Rnd() % 3);
            *(int32_t*)(init[k] + 0xc) = (int32_t)(Rnd() % 0x20);
            hinit[k][9] = Rnd() % 5 == 0 ? 0 : 1;
            *(int32_t*)(hinit[k] + 4) = Rnd() % 2 ? 0 : (int32_t)(Rnd() % 100);
            hinit[k][0xa] = (uint8_t)(Rnd() % 2 ? 0xc : 0x10);
        }
        uint32_t frame = Rnd();
        std::string logs[2];
        for (int sd = 0; sd < 2; ++sd) {
            for (int k = 0; k < 5; ++k) {
                memcpy(g_b83Msgs[k], init[k], 0x30);
                memcpy(g_b83Hdrs[k], hinit[k], 0x40);
                *(uint8_t**)g_b83Msgs[k] = k + 1 < n ? g_b83Msgs[k + 1] : nullptr;
                *(uint8_t**)(g_b83Msgs[k] + 4) = g_b83Hdrs[k];
            }
            g_b83List[0] = n ? (uint32_t)(uintptr_t)g_b83Msgs[0] : 0;
            memset(g_b83Copies, 0, sizeof g_b83Copies);
            g_b83Copy = 0;
            logs[sd] = t.Run([&] {
                if (sd) rt3::Net_ProcessIncoming(s, 0, frame);
                else ((void(__fastcall*)(uint8_t*, int, uint32_t))0x46ad80)(s, 0, frame);
                for (int k = 0; k < n && k < 5; ++k)
                    Logf("m%d hdr %d data %d flags %x frame %x", k, (int)(*(uint8_t**)(g_b83Msgs[k] + 4) - g_b83Copies[0]),
                         (int)(*(uint8_t**)(g_b83Msgs[k] + 8) - g_b83Copies[0]), *(uint32_t*)(g_b83Msgs[k] + 0x20),
                         *(uint32_t*)(g_b83Msgs[k] + 0x24));
                Logf("count %d copies %08x", *(int32_t*)(s + 0x988c), *(uint32_t*)(g_b83Copies[0] + 4));
            });
        }
        CompareLogs(logs[0], logs[1], "net process incoming", it);
    }
}

