int32_t FakeB84HashQuiet(const char* name) {
    char buf[64];
    if (!strchr(name, '.')) {
        sprintf(buf, "%s_A.dds", name);
        name = buf;
    }
    uint32_t h = 0;
    for (const char* p = name; *p; ++p) h = h * 31 + (uint8_t)*p;
    return (int32_t)(h & 0xffff);
}
int32_t __fastcall FakeB84Hash(uint8_t* t, int, const char* name) {
    uint32_t h = 0;
    for (const char* p = name; *p; ++p) h = h * 31 + (uint8_t)*p;
    Logf("hash [%s]", name);
    return (int32_t)(h & 0xffff);
}
int32_t __fastcall FakeB84Locate(uint8_t* t, int, int32_t id, int32_t* a, int32_t* b, int32_t* c, int32_t fatal) {
    int32_t r = (g_b84Exists >> (id % 31)) & 1;
    Logf("locate %d %d -> %d", id, fatal, r);
    *a = 1;
    *b = 2;
    *c = 3;
    return r;
}
