struct B110Rect {
    int32_t l, t, r, b;
};
int32_t __stdcall FakeB110Draw(void* self, const char* s, int32_t n, B110Rect* rc, uint32_t fmt, uint32_t col) {
    int32_t len = (int32_t)strlen(s);
    int32_t wide = 0;
    for (int k = 0; k < len; ++k) wide += (s[k] == 'm' || s[k] == 'W') ? 11 : (s[k] == ' ' ? 4 : 7);
    int32_t boxW = rc->r - rc->l;
    int32_t lines = boxW > 0 ? 1 + wide / boxW : 1;
    rc->r = rc->l + (wide < boxW ? wide : boxW);
    rc->b = rc->t + 14 * lines;
    Logf("draw [%s] %d %x %x -> %d %d", s, n, fmt, col, rc->r, rc->b);
    return 14 * lines;
}
