    t.Add(0x53c000, (void*)&rt3::Pack_Release, (void*)&FakeB175Release);
    t.Add(0x547e30, (void*)&rt3::Render_ScreenSpaceAll, (void*)&FakeB175Screen);
    t.Add(0x545520, (void*)&rt3::Renderer_SetTexture, (void*)&FakeB172SetTex);
    IatSlot ticks(0x5c8068, (void*)&FakeB175Ticks);
    static void* devVt[90];
    static void* vbVt[16];
    devVt[0xc8 / 4] = (void*)&FakeB163RS;
    devVt[0x130 / 4] = (void*)&FakeB171Shader;
    devVt[0x14c / 4] = (void*)&FakeB171Stream;
    devVt[0x90 / 4] = (void*)&FakeB175Clear;
    devVt[0x88 / 4] = (void*)&FakeB175Begin;
    devVt[0x8c / 4] = (void*)&FakeB175End;
    devVt[0x3c / 4] = (void*)&FakeB175Present;
    devVt[0x118 / 4] = (void*)&FakeB175Draw;
    devVt[0xf4 / 4] = (void*)&FakeB172Tex;
    devVt[0x7c / 4] = (void*)&FakeB175Target;
    vbVt[0x2c / 4] = (void*)&FakeB175Lock;
    vbVt[0x30 / 4] = (void*)&FakeB163Unlock;
    static void* dev[1] = { devVt };
    static void* vb[1] = { vbVt };
    static uint8_t rend[0x3800], opts[0x40], stageTex[0x10];
    int32_t savedC = *(int32_t*)0xccd824;
    for (int it = 0; it < 10; ++it) {
        std::string logs[2];
        for (int s = 0; s < 2; ++s) {
            memset(rend, 0, sizeof rend);
            memset(g_b175Vb, 0, sizeof g_b175Vb);
            memset(stageTex, 0x22, sizeof stageTex);
            *(void**)(rend + 0x25df) = dev;
            *(void**)(rend + 0x2647) = (it % 4 == 3) ? nullptr : vb;
            *(void**)(rend + 0x2637) = (it & 1) ? vb : nullptr;
            *(uint8_t**)(rend + 0x83c) = opts;
            *(uint8_t**)(rend + 0x2593) = stageTex;
            *(int32_t*)(rend + 0x258f) = it % 3;
            *(void**)(rend + 0x2607) = (void*)0x2607;
            *(void**)(rend + 0x260b) = (void*)0x260b;
            opts[0x22] = (uint8_t)(it % 2);
            rend[0x254a] = (uint8_t)(it % 3 == 1);
            rend[0x254c] = (uint8_t)(it % 5 == 2);
            g_b175Clock = 0xfffff000u * (it == 7) + 1000 * it;
            g_b175Step = (it == 5) ? 1500 : 90 + 37 * it;
            *(int32_t*)0xccd824 = 3;
            ((void(__cdecl*)(unsigned))0x5a299e)(1234 + it);
            if (it % 4 == 3) *(void**)(rend + 0x2647) = vb;
            logs[s] = t.Run([&] {
                double v = s ? rt3::Render_Benchmark(rend) : ((double(__fastcall*)(uint8_t*))0x54c420)(rend);
                uint32_t h = 0;
                for (size_t i = 0; i < sizeof g_b175Vb / 4; ++i) h = h * 31 + g_b175Vb[i];
                int nextRand = ((int(__cdecl*)())0x5a29ab)();
                Logf("v %.9g r %d %d %p %d vb %08x rand %d c %d st %08x", v, *(int32_t*)(rend + 0x370d), *(int32_t*)(rend + 0x3711), *(void**)(rend + 0x2637),
                     rend[0x254c], h, nextRand, *(int32_t*)0xccd824, *(uint32_t*)stageTex);
            });
        }
        CompareLogs(logs[0], logs[1], "render benchmark", it);
    }
