DIFFTEST(game_MapSmoothAroundAndRescale) {
    UiTrace t;
    t.Add(0x44d410, (void*)&rt3::Map_CellsChangedImpl, (void*)&FakeB299Changed);
    for (int it = 0; it < 400; ++it) {
        std::string logs[2];
        for (int s = 0; s < 2; ++s) {
            uint32_t r = (uint32_t)it * 2654435761u + 53;
            auto rnd = [&](int m) {
                r = r * 1103515245u + 12345u;
                return (int)((r >> 16) % (uint32_t)m);
            };
            memset(g_b299Map, 0, sizeof g_b299Map);
            int32_t w = 8 + rnd(7), h = 8 + rnd(7);
            *(int32_t*)(g_b299Map + 0x15d9) = w;
            *(int32_t*)(g_b299Map + 0x15d5) = h;
            *(int32_t*)(g_b299Map + 0x2155) = w;
            *(float**)(g_b299Map + 0x1605) = g_b299H;
            *(uint8_t**)(g_b299Map + 0x2135) = g_b299Flags;
            for (int k = 0; k < 256; ++k) {
                g_b299H[k] = rnd(10) == 0 ? 3999.5f + (float)rnd(3) : (float)rnd(400) * 0.03125f;
                g_b299Flags[k] = (uint8_t)rnd(4);
            }
            if (it % 13 == 0) memset(g_b299H, 0, sizeof g_b299H);
            int32_t cx = rnd(16), cy = rnd(16), rad = rnd(5), mode = rnd(5) - 1;
            float str = 0.25f * (float)(rnd(6) - 1), scale = 0.125f * (float)(rnd(16) - 8);
            logs[s] = t.Run([&] {
                if (it % 2) {
                    if (s) rt3::Map_SmoothAround(g_b299Map, 0, cx, cy, rad, str);
                    else ((void(__fastcall*)(uint8_t*, int, int32_t, int32_t, int32_t, float))0x44d4e0)(g_b299Map, 0, cx, cy, rad, str);
                } else {
                    if (s) rt3::Map_RescaleHeights(g_b299Map, 0, scale, mode);
                    else ((void(__fastcall*)(uint8_t*, int, float, int32_t))0x44e2e0)(g_b299Map, 0, scale, mode);
                }
                uint32_t hh = 0;
                for (int k = 0; k < 256; ++k) hh = hh * 31 + *(uint32_t*)&g_b299H[k];
                Logf("heights %08x", hh);
            });
        }
        CompareLogs(logs[0], logs[1], "map smooth around and rescale", it);
    }
}

