    t.Add(0x5193f0, (void*)&rt3::GetString, (void*)&FakeB317Str);
    uint8_t keepTable[4 * 64];
    memcpy(keepTable, (void*)0x622b48, sizeof keepTable);
    const uint32_t gl[] = { 0x62be68, 0x6d3b64, 0x6cec78, 0x6d3b40, 0x6d3b44 };
    const int n = sizeof gl / sizeof gl[0];
    uint32_t saved[n];
    for (int i = 0; i < n; ++i) saved[i] = *(uint32_t*)gl[i];
    g_b317Vt[0] = (void*)&FakeB317V0, g_b317Vt[4] = (void*)&FakeB317V4;
