    *(uint8_t**)0x62be68 = g_b317Cam;
    *(uint32_t*)0x6cec78 = 0xec78, *(uint32_t*)0x6d3b40 = 0x3b40, *(uint32_t*)0x6d3b44 = 0x3b44;
    strcpy((char*)g_b317Co + 4, "Player");
