bool B351(int k) { return (g_b351Bits >> (k % 32)) & 1; }
B351Table* B351T(Collection* c) {
    for (auto& t : g_b351)
        if ((void*)c == (void*)&t) return &t;
    return nullptr;
}
int32_t __fastcall FakeB351Count(Collection* c) {
    B351Table* t = B351T(c);
    int k = 0;
    for (int i = 0; i < t->n; ++i) k += t->alive[i];
    return k;
}
uint32_t __fastcall FakeB351IdAt(Collection* c, int, uint32_t pos, int32_t z) {
    B351Table* t = B351T(c);
    for (int i = 0, k = 0; i < t->n; ++i)
        if (t->alive[i] && k++ == (int)pos) return (uint32_t)(i + 1);
    return 0;
}
