DIFFTEST(game_AIConnectCity) {
    UiTrace t;
    B421Hooks(t);
    t.Add(0x404640, (void*)&rt3::AI_ConnectCityToPiece, (void*)&FakeB421ToPiece);
    B421Globals g;
    for (int it = 0; it < 3000; ++it) {
        std::string logs[2];
        for (int s = 0; s < 2; ++s) {
            B421Case c = B421Setup(it);
            if (c.out) c.out = &c.cost;
            logs[s] = t.Run([&] {
                const int32_t ret = s ? rt3::AI_ConnectCity(c.ai, 0, c.city, c.estimate, c.out, &c.toPiece, &c.fromPiece)
                                      : ((int32_t(__fastcall*)(int32_t*, int, int32_t, int32_t, float*, int32_t*, int32_t*))0x4046a0)(
                                            c.ai, 0, c.city, c.estimate, c.out, &c.toPiece, &c.fromPiece);
                Logf("ret %d to %d from %d", ret, c.toPiece, c.fromPiece);
            });
        }
        CompareLogs(logs[0], logs[1], "ai connect city", it);
    }
}

