DIFFTEST(game_AppEvents) {
    UiTrace t;
    B435Hooks(t);
    B435Globals g;
    for (int it = 0; it < 6000; ++it) {
        const int which = it % 4;
        std::string logs[2];
        for (int s = 0; s < 2; ++s) {
            B435Setup(it);
            static const uint32_t types[7] = { 0, 1, 3, 4, 0xcc, 0xcd, 5 };
            uint32_t ev[12] = {};
            ev[0] = types[(it >> 2) % 7], ev[2] = (uint32_t)(it % 11);
            logs[s] = t.Run([&] {
                int32_t ret = 0;
                if (which == 0) ret = s ? rt3::App_HandleEvent(g_b435App, 0, ev) : ((int32_t(__fastcall*)(uint8_t*, int, uint32_t*))0x483a10)(g_b435App, 0, ev);
                else if (which == 1) ret = s ? rt3::App_DispatchEvent(g_b435App, 0, ev) : ((int32_t(__fastcall*)(uint8_t*, int, uint32_t*))0x483dd0)(g_b435App, 0, ev);
                else if (which == 2) {
                    if (s) rt3::App_PumpInput(g_b435App);
                    else ((void(__fastcall*)(uint8_t*))0x483ea0)(g_b435App);
                } else {
                    ret = s ? rt3::App_Frame(g_b435App) : ((int32_t(__fastcall*)(uint8_t*))0x483f70)(g_b435App);
                }
                Logf("ret %d quit %d music %d sess %d ren %d %d a501 %d cam %p posted %d", ret, *(int32_t*)(g_b435App + 0x10), *(int32_t*)(g_b435Music + 0x114),
                     B435Ptr(*(void**)0x6cd8d8), g_b435Ren[0x3747], g_b435Ren[0x3748], *(int32_t*)(g_b435App + 0x501), *(void**)(g_b435Opt + 0x28),
                     *(int32_t*)0x6ae3c4);
            });
        }
        CompareLogs(logs[0], logs[1], "app events", it);
    }
}

// Extra patches on top of a running UiTrace, undone at scope end (a nested
// UiTrace would reset the shared patch table and leave the outer ones in).
struct B435Nested {
    int start = g_npatch;
    void Add(uint32_t exe, void* ours, void* fn) {
        if (exe) Hook((void*)exe, fn);
        if (ours) Hook(ours, fn);
        // The rewrite registered for `exe` (called directly by rewritten code), if another.
        void* reg = exe ? hook::Find(exe) : nullptr;
        if (reg && reg != ours) Hook(reg, fn);
    }
    ~B435Nested() {
        for (int k = g_npatch - 1; k >= start; --k) {
            Patch& pt = g_patches[k];
            DWORD prot;
            VirtualProtect(pt.at, 5, PAGE_EXECUTE_READWRITE, &prot);
            memcpy(pt.at, pt.saved, 5);
            VirtualProtect(pt.at, 5, prot, &prot);
            FlushInstructionCache(GetCurrentProcess(), pt.at, 5);
        }
        g_npatch = start;
    }
};
DIFFTEST(game_AppRunAndWinMain) {
    UiTrace t;
    B435Hooks(t);
    t.Add(0x483f70, (void*)&rt3::App_Frame, (void*)&FakeB435AppFrame);
    B435Globals g;
    // WinMain and App_Run touch much of the exe's state: all of .data goes back afterwards.
    static uint8_t* const kData = (uint8_t*)0x5ed000;
    const size_t kDataSize = 0x7ce8e4;
    uint8_t* dataCopy = (uint8_t*)malloc(kDataSize);
    const unsigned int fpu = _control87(0, 0); // the original's App_Run may switch the x87 precision
    memcpy(dataCopy, kData, kDataSize);
    char saved1[0x10780], saved2[0x1c605];
    memcpy(saved1, (const void*)0x6103a0, sizeof saved1);
    memcpy(saved2, (const void*)0x5f3d9c, sizeof saved2);
    for (int it = 0; it < 600; ++it) {
        std::string logs[2];
        for (int s = 0; s < 2; ++s) {
            B435Setup(it);
            logs[s] = t.Run([&] {
                if (it & 1) {
                    if (s) rt3::App_Run(g_b435App, 0, (void*)0x400000);
                    else ((void(__fastcall*)(uint8_t*, int, void*))0x4840e0)(g_b435App, 0, (void*)0x400000);
                } else {
                    B435Nested t2;
                    t2.Add(0x4840e0, (void*)&rt3::App_Run, (void*)&FakeB435RunFake);
                    t2.Add(0x51d870, (void*)&rt3::StartClock, (void*)&FakeB435StartClock);
                    t2.Add(0x55da40, (void*)&rt3::SysInfo_Init, (void*)&FakeB435SysInit);
                    t2.Add(0x518d50, (void*)&rt3::ResetRand, (void*)&FakeB435ResetRand);
                    t2.Add(0x481d00, (void*)&rt3::Cmdline_Parse, (void*)&FakeB435Cmdline);
                    t2.Add(0x53b010, (void*)&rt3::Set_ccba28, (void*)&FakeB435Ccba28);
                    t2.Add(0x54e6d0, (void*)&rt3::Keyboard_SaveScrollLock, (void*)&FakeB435SaveLock);
                    t2.Add(0x481fd0, (void*)&rt3::Game_InitStart, (void*)&FakeB435InitStart);
                    t2.Add(0x47bbd0, (void*)&rt3::ReturnThis47bbd0, (void*)&FakeB435Lobby);
                    t2.Add(0x47bbe0, (void*)&rt3::Nop47bbe0, (void*)&FakeB435LobbyD);
                    t2.Add(0x53b020, (void*)&rt3::Mem_Shutdown, (void*)&FakeB435MemShutdown);
                    t2.Add(0x55d3a0, (void*)&rt3::SysInfo_Nop, (void*)&FakeB435SysNop);
                    t2.Add(0x54e700, (void*)&rt3::Keyboard_RestoreScrollLock, (void*)&FakeB435RestoreLock);
                    char cmd[] = "-test";
                    // The test DLL sends 0x484440 to its runner: the original entry runs with its first two
                    // instructions (6 bytes) put back for the call.
                    static const uint8_t kEntry[6] = { 0x8b, 0x44, 0x24, 0x10, 0x6a, 0x00 };
                    uint8_t* entry = (uint8_t*)0x484440;
                    uint8_t patched[6];
                    DWORD prot;
                    int ret;
                    if (s) {
                        ret = rt3::Game_WinMain((void*)0x400000, nullptr, cmd, 5);
                    } else {
                        VirtualProtect(entry, 6, PAGE_EXECUTE_READWRITE, &prot);
                        memcpy(patched, entry, 6), memcpy(entry, kEntry, 6);
                        ret = ((int(__stdcall*)(HINSTANCE, HINSTANCE, char*, int))0x484440)((HINSTANCE)0x400000, nullptr, cmd, 5);
                        memcpy(entry, patched, 6);
                        VirtualProtect(entry, 6, prot, &prot);
                    }
                    Logf("winmain %d show %d title [%.17s]", ret, *(int32_t*)0x6cec58, (const char*)0x624b68);
                }
                Logf("end copies %d app %d music %p menu %x opt %p fmt %x intro %d", g_b435Copies, *(int32_t*)(g_b435App + 0xa8), *(void**)(g_b435App + 0x14),
                     *(uint32_t*)0x6ada8c, *(void**)0x6d4024, *(uint32_t*)0x620e98, *(int32_t*)0x624308);
            });
        }
        CompareLogs(logs[0], logs[1], "app run / winmain", it);
    }
    memcpy((void*)0x6103a0, saved1, sizeof saved1);
    memcpy((void*)0x5f3d9c, saved2, sizeof saved2);
    memcpy(kData, dataCopy, kDataSize);
    free(dataCopy);
    _control87(fpu, 0xffffffff);
}

