            *(uint8_t**)0x6d401c = g_genBuf[4 + 4];
            *(uint8_t**)0x6d1a8c = g_genBuf[4 + 5];
            *(uint8_t**)0xccbb20 = g_genBuf[4 + 6];
            *(uint8_t**)0x6cd8d8 = g_genBuf[4 + 7];
