    t.Add(0x5193f0, (void*)&rt3::GetString, (void*)&FakeB399Str);
    static const GenCase cases[] = {
        { 0x4adde0, (const void*)&rt3::Train_Arrive, "Vq-" },
        { 0x4c23a0, (const void*)&rt3::CompanyCredit_DrawCb, "V--ffffi" },
        { 0x40e4e0, (const void*)&rt3::StationBuilding_Hover, "Vq-" }
    };
    const int NC = (int)(sizeof cases / sizeof cases[0]);
    const int NP = (int)(sizeof kb458Ptr / 4), NI = (int)(sizeof kb458Int / 4);
    uint32_t savedP[sizeof kb458Ptr / 4], savedI[sizeof kb458Int / 4];
    for (int i = 0; i < NP; ++i) savedP[i] = *(uint32_t*)kb458Ptr[i];
    for (int i = 0; i < NI; ++i) savedI[i] = *(uint32_t*)kb458Int[i];
    for (int k = 0; k < 64; ++k) g_genVtbl[k] = (void*)&GenFakeb458_v0;
    g_genVtbl[22] = (void*)&GenFakeb458_v22, g_genVtbl[26] = (void*)&GenFakeb458_v26, g_genVtbl[32] = (void*)&GenFakeb458_vp;
    g_genVtbl[2] = (void*)&GenFakeb458_v2; // vtable +8: Collection remove (one argument)

    static const uint32_t kSmall[6] = { 0, 1, 2, 0xffffffff, 0x3c, 0x12 };
    for (int it = 0; it < 120 * NC; ++it) {
        const GenCase& c = cases[it % NC];
        std::string logs[2];
        for (int s = 0; s < 2; ++s) {
            g_genBits = (uint32_t)it * 2654435761u + 0xb458;
            for (int o = 0; o < 4; ++o)
                for (int k = 0; k < 0x100; ++k) {
                    const uint32_t r = GenDraw() % 4;
                    ((uint32_t*)g_genObj[o])[k] = r < 2 ? (uint32_t)(uintptr_t)g_genObj[GenDraw() % 4] : r == 2 ? kSmall[GenDraw() % 6] : GenDraw();
                }
            for (int o = 0; o < 4; ++o) {
                ((void**)g_genObj[o])[0] = g_genVtbl;
                ((uint32_t*)g_genObj[o])[1] = (uint32_t)(uintptr_t)g_genObj[(o + 1) % 4];
                ((uint32_t*)g_genObj[o])[2] = (uint32_t)(uintptr_t)g_genObj[(o + 2) % 4];
                ((int32_t*)g_genObj[o])[3] = (int32_t)(GenDraw() % 3) - 1;
                memcpy(g_genObj[o] + 0x40, g_genObj[o], 0x10); // 'p' may point 0x40 in: the same header
            }
            for (int b = 0; b < 4; ++b) memset(g_genBuf[b], 0, 0x2000);
            *(int32_t*)(g_genBuf[0] + 0x15dd) = 8, *(uint8_t**)(g_genBuf[0] + 0x165d) = g_genBuf[1];
            for (int i = 0; i < NP; ++i) {
                uint8_t* b = g_genBuf[4 + i % 20];
                memset(b, 0, 0x2000); // the whole hashed range: both sides start alike
                ((void**)b)[0] = g_genVtbl;
                *(uint32_t*)kb458Ptr[i] = GenDraw() % 5 ? (uint32_t)(uintptr_t)b : 0;
            }
            *(uint8_t**)0x62ba84 = g_genBuf[4 + 0];
            *(uint8_t**)0x6cec20 = g_genBuf[4 + 1];
            *(uint8_t**)0x6ada90 = g_genBuf[4 + 2];
            *(uint8_t**)0x62b26c = g_genBuf[4 + 3];
            *(uint8_t**)0x6cec78 = g_genBuf[4 + 6];
            *(uint8_t**)0x62c120 = g_genBuf[4 + 9];
            *(uint8_t**)0x62ba8c = g_genBuf[4 + 11];
            for (int i = 0; i < NI; ++i) *(uint32_t*)kb458Int[i] = kSmall[GenDraw() % 6];
            g_genListHead = g_genList[0], *(uint8_t**)g_genList[0] = g_genList[1], *(uint8_t**)g_genList[1] = GenDraw() % 2 ? g_genList[2] : nullptr;
            *(uint8_t**)g_genList[2] = nullptr;
            memset(g_genBig + 0x114000, 0, 0x2000); // the hashed engine fields: both sides start alike

            g_genVtbl[2] = (void*)&GenFakeb458_hook;
            for (int k = 0; k < 4; ++k) *(uint32_t*)(g_genBig + k * 0x1000 + 4) = 0, *(uint16_t*)(g_genBig + k * 0x1000) = (uint16_t)k;
            if (uint8_t* p = *(uint8_t**)0x6d0818) *(int32_t*)(p + 0x90) = (int32_t)(GenDraw() % 3);
            uint8_t* map = *(uint8_t**)0x62c120;
            static const int32_t modes[4] = { 0, 3, 0x15, 7 };
            *(int32_t*)(map + 0x2175) = modes[GenDraw() % 4];
            *(int32_t*)(map + 0x2171) = (int32_t)(GenDraw() % 2), *(int32_t*)(map + 0x2179) = (int32_t)(GenDraw() % 3);
            uint8_t* cargo = *(uint8_t**)0x62ba8c;
            for (int k = 0; k < 4; ++k) *(int32_t*)(cargo + 0x9a + k * 4) = GenDraw() % 2 ? -1 : 1;
            if (uint8_t* f = *(uint8_t**)0x6d12f0) *(int32_t*)(f + 0x78) = (int32_t)(GenDraw() % 5);
            uint8_t* q = g_genBuf[2];
            memset(q, 0, 0x2000);
            ((void**)q)[0] = g_genVtbl;
            *(int32_t*)(q + 0x41) = GenDraw() % 2 ? -1 : 1;
            *(uint32_t*)(q + 0xa0) = 2, *(uint32_t*)(q + 0x29) = GenDraw() % 2 ? 5 : 0;
            q[0x3d4] = (uint8_t)(GenDraw() % 4 ? 1 : 0);
            *(uint32_t*)(q + 0x2a8) = GenDraw() % 2, *(uint32_t*)(q + 0x3cc) = 3;
            *(int32_t*)(q + 0x276) = (int32_t)(GenDraw() % 2);

            g_genF = (float)(GenDraw() % 100) / 4.0f;
            const char* sp = c.spec;
            const int noret = *sp == 'V';
            if (noret) ++sp;
            const int fp = *sp == 'F';
            if (fp) ++sp;
            auto value = [&](char k) -> uint32_t {

                if (k == 'm') return (uint32_t)(uintptr_t)g_genBuf[0];
                if (k == 'q') return (uint32_t)(uintptr_t)g_genBuf[2];
                if (k == 'r') return (uint32_t)(uintptr_t)g_genBuf[3];
                if (k == 'c') return GenDraw() % 8;
                if (k == 'k') return GenDraw() % 2 ? 0x7fff : 3;
                if (k == 'z') return GenDraw() % 3 ? (uint32_t)(uintptr_t)g_genObj[GenDraw() % 4] : 0;
                return GenValue(k);
            };
            const uint32_t rc = value(sp[0]), rd = value(sp[1]);
            uint32_t a[8] = {};
            for (int k = 0; k < 8 && sp[2 + k]; ++k) a[k] = value(sp[2 + k]);
            logs[s] = t.Run([&] {
                double f = 0;
                const uint32_t r = GenCall(s ? c.ours : (const void*)(uintptr_t)c.exe, rc, rd, a, fp, &f);
                uint64_t fb;
                memcpy(&fb, &f, 8);
                if (!noret) Logf("ret %s fp %08x%08x", fp ? "-" : GenName(r), (uint32_t)(fb >> 32), (uint32_t)fb);
                for (int i = 0; i < NP; ++i) Logf("g %x %s", kb458Ptr[i], GenName(*(uint32_t*)kb458Ptr[i]));
                for (int i = 0; i < NI; ++i) Logf("g %x %08x", kb458Int[i], *(uint32_t*)kb458Int[i]);
                for (int o = 0; o < 4; ++o) Logf("obj %d %08x", o, Fnv(g_genObj[o], 0x400));
                for (int b = 0; b < 24; ++b) Logf("buf %d %08x", b, Fnv(g_genBuf[b], 0x2000));
                for (int b = 0; b < 3; ++b) Logf("list %d %08x", b, Fnv(g_genList[b], 0x100));
                Logf("big %08x", Fnv(g_genBig + 0x114000, 0x2000));
            });
        }
        char what[64];
        sprintf(what, "small callback %x", c.exe);
        CompareLogs(logs[0], logs[1], what, it);
    }
    for (int i = 0; i < NP; ++i) *(uint32_t*)kb458Ptr[i] = savedP[i];
    for (int i = 0; i < NI; ++i) *(uint32_t*)kb458Int[i] = savedI[i];

