// picked colour / portrait.
uint32_t __fastcall FakeB479Dialog(const char* text, int32_t type, uint32_t px, uint32_t py, uint32_t p4, uint32_t place, uint32_t pic, uint32_t h,
                                   uint32_t button, uint32_t a8, uint32_t a9, uint32_t a10, uint32_t a11, uint32_t a12, uint32_t a13, uint32_t a14,
                                   uint32_t a15) {
    Logf("dialog [%s] %d %x %x %x %x %x %x %x", text, type, px, py, p4, place, pic, h, a8);
    if (type == 9) {
        static const char* const names[5] = { "", "Acme Rail", "Big Lines", "New Co", "A name far too long for any player or company to use here" };
        char* name = (char*)(uintptr_t)button;
        const char* n = names[GenDraw() % 5];
        if (*n || GenDraw() % 2) strcpy(name, n);
        if (GenDraw() % 2) *(uint32_t*)0x622090 = GenDraw() % 4;
        if (GenDraw() % 2) *(uint32_t*)0x622094 = GenDraw() % 4;
    }
    return 0;
}

