// Obj_TypeValue / Obj_TypeRecord: the ambient sound rate, name, range and count.
int32_t __fastcall FakeB482TypeValue(uint8_t* t, int, int32_t* out) {
    const float rate = (float)(GenDraw() % 8) * 0.5f;
    memcpy(out, &rate, 4);
    const int32_t r = GenDraw() % 3 != 0;
    Logf("typevalue %s -> %g %d", GenName((uint32_t)(uintptr_t)t), rate, r);
    return r;
}
int32_t __fastcall FakeB482TypeRecord(uint8_t* t, int, char* name, int32_t* a, int32_t* b, int32_t* count) {
    strcpy(name, GenDraw() % 2 ? "cow" : "bird");
    *a = 7;
    const float range = (float)(GenDraw() % 6) * 0.75f;
    memcpy(b, &range, 4);
    *count = 1 + GenDraw() % 4;
    const int32_t r = GenDraw() % 4 != 0;
    Logf("typerecord %s -> [%s] %g %d %d", GenName((uint32_t)(uintptr_t)t), name, range, *count, r);
    return r;
}

