                memcpy(&fb, &f, 8);
                if (!noret) Logf("ret %s fp %08x%08x", fp ? "-" : GenName(r), (uint32_t)(fb >> 32), (uint32_t)fb);
                for (int i = 0; i < NP; ++i) Logf("g %x %s", kb491Ptr[i], GenName(*(uint32_t*)kb491Ptr[i]));
